import { describe, expect, it } from 'vitest';
import { Add, PolynomialRingBase, Pow, QQ, QuotientRing, Sym, add, pow, rational, symbols } from '../../../src';
import { sympyStr } from '../../sympy-str';

describe("doctests of sympy.polys.domains.quotientring", () => {
  it("QQ.old_poly_ring(x).quotient_ring(I)", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'grevlex').quotientRing(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(add(1, pow(x, 3)))))).toBe('QQ[x]/<x**3 + 1>');
  });
  it("QQ.old_poly_ring(x)/I", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'grevlex').quotientRing(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(add(1, pow(x, 3)))))).toBe('QQ[x]/<x**3 + 1>');
  });
  it("QQ.old_poly_ring(x)/[x**3 + 1]", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'grevlex').quotientRing([add(1, pow(x, 3))]))).toBe('QQ[x]/<x**3 + 1>');
  });
  it("(QQ.old_poly_ring(x)/[x**2 + 1]).free_module(2)", () => {
    const x = new Sym('x');
    expect(sympyStr(new QuotientRing(new PolynomialRingBase(QQ, [x], 'grevlex'), new PolynomialRingBase(QQ, [x], 'grevlex').ideal(add(1, pow(x, 2)))).freeModule(rational(2)))).toBe('(QQ[x]/<x**2 + 1>)**2');
  });
});

